-- 1. OPUS — LNK_CLAIM_PARTY -- (a) missing links (RAW -> link)   [Implemented]
-- 1 RAW feed(s): stg2_link_clm_interested_parties__claim_party <-
-- stg_partner__clm_interested_parties. FKs: PARTY_HKEY -> HUB_PARTY, CLAIM_HKEY ->
-- HUB_CLAIM. A RAW relationship counts only when every FK key is present
-- (automate_dv.link does not load a row with a NULL FK). Link hash keys are recomputed
-- from RAW with the stg2 NK expressions (automate_dv 0.11.5 MD5_BINARY formula).
----------------------------------------------------------------------------------------
-- SQL query (a) -- counts per feed
with src as (
    -- via stg2_link_clm_interested_parties__claim_party <- stg_partner__clm_interested_parties
    select 'stg2_link_clm_interested_parties__claim_party <- stg_partner__clm_interested_parties' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) || '|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) as CLAIM_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.CLM_INTERESTED_PARTIES
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) is not null
)
select 'OPUS' as project, 'LNK_CLAIM_PARTY' as link,
       coalesce(src.src_feed, '== TOTAL (distinct across feeds) ==') as src_feed,
       count(distinct src.link_hkey) as source_relationships,
       count(distinct iff(l.k is not null, src.link_hkey, null)) as present_in_link,
       source_relationships - present_in_link as missing_links,
       iff(missing_links = 0, 'PASS', 'FAIL') as status
  from src
  left join (select distinct CLAIM_PARTY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_CLAIM_PARTY) l on l.k = src.link_hkey
 group by grouping sets ((src.src_feed), ())
 order by grouping(src.src_feed) desc, src.src_feed;

-- SQL query (a) drill-down -- first 100 missing relationships
with src as (
    -- via stg2_link_clm_interested_parties__claim_party <- stg_partner__clm_interested_parties
    select 'stg2_link_clm_interested_parties__claim_party <- stg_partner__clm_interested_parties' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) || '|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) as CLAIM_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.CLM_INTERESTED_PARTIES
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) is not null
)
select 'OPUS' as project, 'LNK_CLAIM_PARTY' as link, src_feed, to_varchar(link_hkey, 'HEX') as missing_link_hkey,
       to_varchar(PARTY_HKEY, 'HEX') as PARTY_HKEY, to_varchar(CLAIM_HKEY, 'HEX') as CLAIM_HKEY
  from src
 where not exists (select 1 from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_CLAIM_PARTY l where l.CLAIM_PARTY_HKEY = src.link_hkey)
 order by src_feed
 limit 100;



