-- 3. OPUS — LNK_CLAIM_PARTY -- (c) unexpected links (link -> RAW)   [Informational]
-- Not part of the pass criterion: link rows of this project whose relationship is no
-- longer in RAW.
----------------------------------------------------------------------------------------
with src as (
    -- via stg2_link_clm_interested_parties__claim_party <- stg_partner__clm_interested_parties
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) || '|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) as CLAIM_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.CLM_INTERESTED_PARTIES
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim("CLAIM_ID"::varchar), '')) AS VARCHAR))), '')) is not null
)
select 'OPUS' as project, 'LNK_CLAIM_PARTY' as link, l.RECORD_SOURCE,
       count(*) as link_rows,
       count_if(k.link_hkey is null) as unexpected_links,
       array_slice(array_agg(iff(k.link_hkey is null, to_varchar(l.CLAIM_PARTY_HKEY, 'HEX'), null)), 0, 3) as examples
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_CLAIM_PARTY l
  left join (select distinct link_hkey from src) k on k.link_hkey = l.CLAIM_PARTY_HKEY
 where startswith(l.RECORD_SOURCE, 'OPUS_')
 group by l.RECORD_SOURCE
 order by l.RECORD_SOURCE;



