    select 'stg2_link_bjaz_t_ckyc_personal_dtls__party_location__permanent <- stg_partner__bjaz_t_ckyc_personal_dtls' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_LOCATION|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_COUNTRY"::varchar), ''))))), ''), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_COUNTRY"::varchar), ''))))), ''), '')) AS VARCHAR))), '')) as LOCATION_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_COUNTRY"::varchar), ''))))), ''), '')) AS VARCHAR))), '')) is not null
)
select 'OPUS' as project, 'LNK_PARTY_LOCATION' as link,
       coalesce(src.src_feed, '== TOTAL (distinct across feeds) ==') as src_feed,
       count(distinct src.link_hkey) as source_relationships,
       count(distinct iff(l.k is not null, src.link_hkey, null)) as present_in_link,
       source_relationships - present_in_link as missing_links,
       iff(missing_links = 0, 'PASS', 'FAIL') as status
  from src
  left join (select distinct PARTY_LOCATION_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_LOCATION) l on l.k = src.link_hkey
 group by grouping sets ((src.src_feed), ())
 order by grouping(src.src_feed) desc, src.src_feed;

-- SQL query (a) drill-down -- first 100 missing relationships
