           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), ''), '')) AS VARCHAR))), '')) as LOCATION_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), ''), '')) AS VARCHAR))), '')) is not null
    union all
    -- via stg2_link_bjaz_t_ckyc_personal_dtls__party_location__permanent <- stg_partner__bjaz_t_ckyc_personal_dtls
    select 'stg2_link_bjaz_t_ckyc_personal_dtls__party_location__permanent <- stg_partner__bjaz_t_ckyc_personal_dtls' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_LOCATION|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_COUNTRY"::varchar), ''))))), ''), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_COUNTRY"::varchar), ''))))), ''), '')) AS VARCHAR))), '')) as LOCATION_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce((nullif(trim("CKYC_NO"::varchar), '')),''))), 'CKYC:')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("PERM_COUNTRY"::varchar), ''))))), ''), '')) AS VARCHAR))), '')) is not null
)
select 'OPUS' as project, 'LNK_PARTY_LOCATION' as link, src_feed, to_varchar(link_hkey, 'HEX') as missing_link_hkey,
       to_varchar(PARTY_HKEY, 'HEX') as PARTY_HKEY, to_varchar(LOCATION_HKEY, 'HEX') as LOCATION_HKEY
  from src
 where not exists (select 1 from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_LOCATION l where l.PARTY_LOCATION_HKEY = src.link_hkey)
 order by src_feed
 limit 100;



----------------------------------------------------------------------------------------
-- 5. OPUS — LNK_PARTY_LOCATION -- (b) orphan links (link FK -> hub)   [Implemented]
-- Link rows scoped to RECORD_SOURCE 'OPUS_%'; every FK must exist in its hub (any
-- project's rows -- shared vault). FKs: PARTY_HKEY -> HUB_PARTY, LOCATION_HKEY ->
-- HUB_LOCATION.
----------------------------------------------------------------------------------------
select 'OPUS' as project, 'LNK_PARTY_LOCATION' as link, 'PARTY_HKEY' as fk_column, 'HUB_PARTY' as hub,
       count(*) as link_rows,
       count_if(l.PARTY_HKEY is null) as null_fk_rows,
       count_if(l.PARTY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.PARTY_HKEY is not null and h.k is null, to_varchar(l.PARTY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_LOCATION l
  left join (select distinct PARTY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_PARTY) h on h.k = l.PARTY_HKEY
 where startswith(l.RECORD_SOURCE, 'OPUS_')
union all
select 'OPUS' as project, 'LNK_PARTY_LOCATION' as link, 'LOCATION_HKEY' as fk_column, 'HUB_LOCATION' as hub,
       count(*) as link_rows,
       count_if(l.LOCATION_HKEY is null) as null_fk_rows,
       count_if(l.LOCATION_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.LOCATION_HKEY is not null and h.k is null, to_varchar(l.LOCATION_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_PARTY_LOCATION l
  left join (select distinct LOCATION_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_LOCATION) h on h.k = l.LOCATION_HKEY
 where startswith(l.RECORD_SOURCE, 'OPUS_')
order by fk_column;



