    select 'stg2_link_azbj_partner_extn__policy_party <- stg_partner__azbj_partner_extn' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) || '|' || (nullif(trim("EXISTING_POLICY_PID"::varchar), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("EXISTING_POLICY_PID"::varchar), '')) AS VARCHAR))), '')) as POLICY_HKEY
