     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("EXISTING_POLICY_PID"::varchar), '')) AS VARCHAR))), '')) is not null
