       to_varchar(PARTY_HKEY, 'HEX') as PARTY_HKEY, to_varchar(POLICY_HKEY, 'HEX') as POLICY_HKEY
  from src
 where not exists (select 1 from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_POLICY_PARTY l where l.POLICY_PARTY_HKEY = src.link_hkey)
 order by src_feed
 limit 100;



----------------------------------------------------------------------------------------
-- 8. OPUS — LNK_POLICY_PARTY -- (b) orphan links (link FK -> hub)   [Implemented]
-- Link rows scoped to RECORD_SOURCE 'OPUS_%'; every FK must exist in its hub (any
-- project's rows -- shared vault). FKs: PARTY_HKEY -> HUB_PARTY, POLICY_HKEY ->
-- HUB_POLICY.
----------------------------------------------------------------------------------------
select 'OPUS' as project, 'LNK_POLICY_PARTY' as link, 'PARTY_HKEY' as fk_column, 'HUB_PARTY' as hub,
       count(*) as link_rows,
       count_if(l.PARTY_HKEY is null) as null_fk_rows,
       count_if(l.PARTY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.PARTY_HKEY is not null and h.k is null, to_varchar(l.PARTY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_POLICY_PARTY l
  left join (select distinct PARTY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_PARTY) h on h.k = l.PARTY_HKEY
 where startswith(l.RECORD_SOURCE, 'OPUS_')
union all
select 'OPUS' as project, 'LNK_POLICY_PARTY' as link, 'POLICY_HKEY' as fk_column, 'HUB_POLICY' as hub,
       count(*) as link_rows,
       count_if(l.POLICY_HKEY is null) as null_fk_rows,
       count_if(l.POLICY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.POLICY_HKEY is not null and h.k is null, to_varchar(l.POLICY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_POLICY_PARTY l
  left join (select distinct POLICY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_POLICY) h on h.k = l.POLICY_HKEY
 where startswith(l.RECORD_SOURCE, 'OPUS_')
order by fk_column;



