           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as POLICY_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) is not null
    union all
    -- via stg2_link_bjaz_sh_mem_dtls_extn__policy_party <- stg_partner__bjaz_sh_mem_dtls_extn
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) || '|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as POLICY_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) is not null
    union all
    -- via stg2_link_bjaz_spp_member_dtls__policy_party <- stg_partner__bjaz_spp_member_dtls
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) || '|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as POLICY_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) is not null
    union all
    -- via stg2_link_bjaz_starpkg_ff_dtls__policy_party <- stg_partner__bjaz_starpkg_ff_dtls
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) || '|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as POLICY_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_STARPKG_FF_DTLS
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) is not null
    union all
    -- via stg2_link_ocp_interested_parties__policy_party <- stg_partner__ocp_interested_parties
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_POLICY_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) || '|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) as PARTY_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) as POLICY_HKEY
      from BAGIC_PREPROD_CURATED_DB.UTILS.OCP_INTERESTED_PARTIES
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), '')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), '')) AS VARCHAR))), '')) is not null
)
select 'OPUS' as project, 'LNK_POLICY_PARTY' as link, l.RECORD_SOURCE,
       count(*) as link_rows,
       count_if(k.link_hkey is null) as unexpected_links,
       array_slice(array_agg(iff(k.link_hkey is null, to_varchar(l.POLICY_PARTY_HKEY, 'HEX'), null)), 0, 3) as examples
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LNK_POLICY_PARTY l
  left join (select distinct link_hkey from src) k on k.link_hkey = l.POLICY_PARTY_HKEY
 where startswith(l.RECORD_SOURCE, 'OPUS_')
 group by l.RECORD_SOURCE
 order by l.RECORD_SOURCE;
